INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 3.414, "カリン", 1, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 190801, 62, -416.5, 0.0, 1000001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 3.099, "カリン", 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 190801, 62, -416.5, 0.0, 1000002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 2.801, "カリン", 3, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 190801, 63, -416.5, 0.0, 1000003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 0.0, "カリン", 4, 2, "報酬がもらえますよ！\nチェックしてみてください", 2, 190801, 63, -416.5, 0.0, 1000004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 2.12, "カリン", 5, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 190801, 64, -363.0, 0.0, 1000005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 1.68, "カリン", 6, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 190801, 64, -363.0, 0.0, 1000006);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 2.33, "カリン", 7, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 190801, 64, -363.0, 0.0, 1000007);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 10201, "2030/01/01 14:59:59", 5.18, "ラビリスタ", 101, 3, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 7, 133701, 61, -285.0, -6.0, 1020101);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 10201, "2030/01/01 14:59:59", 8.77, "クリスティーナ", 201, 1, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 2, 133901, 61, -285.0, -2.0, 1020102);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 10201, "2030/01/01 14:59:59", 15.5, "ネネカ", 301, 6, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 1, 133801, 61, -285.0, 0.0, 1020103);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/02/28 12:00:00", 10202, "2030/01/01 14:59:59", 9.061, "ランファ", 101, 2, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 5, 134301, 61, -285.0, 0.0, 1020201);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/02/28 12:00:00", 10202, "2030/01/01 14:59:59", 7.699, "チカ", 201, 1, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 2, 134401, 61, -285.0, 0.0, 1020202);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/03/31 12:00:00", 10203, "2030/01/01 14:59:59", 8.595, "アオイ", 101, 1, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 2, 134601, 61, -285.0, 0.0, 1020301);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/03/31 12:00:00", 10203, "2030/01/01 14:59:59", 7.758, "クローチェ", 201, 1, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 2, 134501, 61, -285.0, 0.0, 1020302);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 10204, "2030/01/01 14:59:59", 7.0, "ルイズマリー", 101, 2, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 6, 132302, 61, -285.0, 0.0, 1020401);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 10204, "2030/01/01 14:59:59", 7.904, "イロハ", 201, 1, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 2, 132402, 61, -285.0, 0.0, 1020402);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 10204, "2030/01/01 14:59:59", 8.487, "ソノ", 301, 4, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 2, 132502, 61, -285.0, 0.0, 1020403);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/05/31 12:00:00", 10205, "2030/01/01 14:59:59", 8.763, "カノン", 101, 1, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 2, 134901, 61, -285.0, 0.0, 1020502);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/05/31 12:00:00", 10205, "2030/01/01 14:59:59", 6.417, "ツムギ", 201, 1, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 3, 134801, 61, -285.0, 0.0, 1020503);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 10206, "2030/01/01 14:59:59", 10.335, "エリス", 101, 3, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 7, 135001, 61, -285.0, 0.0, 1020601);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 10206, "2030/01/01 14:59:59", 6.281, "シェフィ", 201, 2, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 4, 135101, 61, -285.0, 0.0, 1020602);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 10206, "2030/01/01 14:59:59", 12.244, "プレシア", 301, 1, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 2, 135201, 61, -285.0, 0.0, 1020603);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/07/31 12:00:00", 10207, "2030/01/01 14:59:59", 6.339, "クリア", 101, 2, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 8, 135301, 61, -285.0, 0.0, 1020701);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/07/31 12:00:00", 10207, "2030/01/01 14:59:59", 8.184, "アネモネ", 201, 7, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 9, 135401, 61, -285.0, 0.0, 1020702);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 10208, "2030/01/01 14:59:59", 3.906, "アイラ", 101, 9, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 2, 129101, 61, -285.0, 0.0, 1020801);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 10208, "2030/01/01 14:59:59", 14.465, "シナツ", 201, 1, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 2, 129201, 61, -285.0, 0.0, 1020802);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 10208, "2030/01/01 14:59:59", 8.662, "ヒヨリ", 301, 4, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 3, 100101, 61, -285.0, 0.0, 1020803);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 10208, "2030/01/01 14:59:59", 10.915, "レイ", 401, 1, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 3, 100301, 61, -285.0, 0.0, 1020804);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 10209, "2030/01/01 14:59:59", 6.042, "ユキノ", 101, 1, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 7, 135802, 61, -285.0, 0.0, 1020901);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 10209, "2030/01/01 14:59:59", 9.402, "サツキ", 201, 4, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 1, 135903, 61, -285.0, 0.0, 1020902);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 10209, "2030/01/01 14:59:59", 8.16, "ルルィ", 301, 8, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 1, 136902, 61, -285.0, 0.0, 1020903);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 10210, "2030/01/01 14:59:59", 5.0, "カスミ", 101, 3, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 2, 137401, 61, -285.0, 0.0, 1021001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 10210, "2030/01/01 14:59:59", 8.12, "アラクネ", 201, 4, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 1, 136001, 61, -285.0, 0.0, 1021002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 10210, "2030/01/01 14:59:59", 6.386, "ナーナ", 301, 4, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 2, 136202, 61, -285.0, 0.0, 1021003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/11/30 12:00:00", 10211, "2030/01/01 14:59:59", 7.438, "ユイ", 101, 3, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 4, 136402, 61, -285.0, 0.0, 1021101);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/11/30 12:00:00", 10211, "2030/01/01 14:59:59", 8.35, "ミソラ", 201, 1, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 5, 136302, 61, -285.0, 0.0, 1021102);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 10212, "2030/01/01 14:59:59", 5.0, "シズル", 101, 1, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 2, 136501, 61, -285.0, 0.0, 1021201);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 10212, "2030/01/01 14:59:59", 5.25, "リノ", 201, 1, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 2, 137902, 61, -285.0, 0.0, 1021202);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 10212, "2030/01/01 14:59:59", 7.5, "ラビリスタ", 301, 1, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 2, 106801, 61, -285.0, 0.0, 1021203);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 10213, "2030/01/01 14:59:59", 8.204, "ライラエル", 101, 1, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 2, 126501, 61, -285.0, 0.0, 1021301);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 10213, "2030/01/01 14:59:59", 7.176, "ネフィ＝ネラ", 201, 1, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 2, 129701, 61, -285.0, 0.0, 1021302);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 10213, "2030/01/01 14:59:59", 8.602, "ヴァイオレット", 301, 1, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 5, 133101, 61, -285.0, 0.0, 1021303);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 10213, "2030/01/01 14:59:59", 10.14, "ライラエル", 102, 1, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 3, 138101, 61, -285.0, 0.0, 1021304);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 10213, "2030/01/01 14:59:59", 10.152, "ネフィ＝ネラ", 202, 1, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 7, 138201, 61, -285.0, 0.0, 1021305);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 10213, "2030/01/01 14:59:59", 9.688, "ヴァイオレット", 302, 4, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 3, 138001, 61, -285.0, 0.0, 1021306);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/12 12:00:00", 10213, "2030/01/01 14:59:59", 5.928, "ペコリーヌ", 401, 2, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 1, 138301, 61, -285.0, 0.0, 1021307);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/28 12:00:00", 10214, "2030/01/01 14:59:59", 9.19, "ワカナ", 101, 4, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 2, 138702, 61, -285.0, 0.0, 1021401);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/28 12:00:00", 10214, "2030/01/01 14:59:59", 8.724, "シオリ", 201, 1, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 3, 138802, 61, -285.0, 0.0, 1021402);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 10215, "2030/01/01 14:59:59", 7.758, "グレイス", 101, 4, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 1, 138902, 61, -285.0, 0.0, 1021501);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 10215, "2030/01/01 14:59:59", 6.375, "キョウカ", 201, 6, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 4, 139002, 61, -285.0, 0.0, 1021502);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 10215, "2030/01/01 14:59:59", 6.173, "ルルィ", 301, 6, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 1, 136902, 61, -285.0, 0.0, 1021503);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 10216, "2030/01/01 14:59:59", 4.202, "ミホ", 101, 6, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 2, 139202, 61, -285.0, 0.0, 1021601);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 10216, "2030/01/01 14:59:59", 2.842, "マホ", 201, 6, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 1, 139302, 61, -285.0, 0.0, 1021602);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 10216, "2030/01/01 14:59:59", 4.598, "エリカ", 301, 4, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 1, 139402, 61, -285.0, 0.0, 1021603);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 6.533, "リリ", 101, 4, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 3, 125802, 61, -285.0, 0.0, 1021701);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 5.0, "プレシア", 301, 3, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 3, 126102, 61, -285.0, 0.0, 1021702);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 5.214, "クリア", 201, 3, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 4, 126002, 61, -285.0, 0.0, 1021703);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 8.781, "リリ", 102, 1, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 3, 139501, 61, -285.0, 0.0, 1021704);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 6.529, "クリア", 202, 2, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 1, 139601, 61, -285.0, 0.0, 1021705);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 10217, "2030/01/01 14:59:59", 3.195, "プレシア", 302, 3, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 2, 139701, 61, -285.0, 0.0, 1021706);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/06/30 12:00:00", 10218, "2030/01/01 14:59:59", 12.43, "ルイズマリー", 101, 2, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 3, 139902, 61, -285.0, 0.0, 1021801);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/06/30 12:00:00", 10218, "2030/01/01 14:59:59", 6.35, "クレジッタ", 201, 2, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 3, 140001, 61, -285.0, 0.0, 1021802);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/07/31 12:00:00", 10219, "2030/01/01 14:59:59", 10.23, "フブキ", 101, 1, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 5, 140102, 61, -285.0, 0.0, 1021901);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/07/31 12:00:00", 10219, "2030/01/01 14:59:59", 5.584, "ヴァンピィ", 201, 1, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 2, 140201, 61, -285.0, 0.0, 1021902);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 10220, "2030/01/01 14:59:59", 2.8, "クローチェ", 201, 6, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 3, 126401, 61, -285.0, 0.0, 1022001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 10220, "2030/01/01 14:59:59", 8.9, "ヴルム", 101, 4, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 3, 127802, 61, -285.0, 0.0, 1022002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 10220, "2030/01/01 14:59:59", 4.49, "クローチェ", 202, 2, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 1, 140602, 61, -285.0, 0.0, 1022003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 10220, "2030/01/01 14:59:59", 9.42, "ヴルム", 102, 1, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 3, 140501, 61, -285.0, 0.0, 1022004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 10220, "2030/01/01 14:59:59", 7.0, "リーザ", 301, 4, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 1, 140402, 61, -285.0, 0.0, 1022005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 3.414, "カリン", 1, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 190805, 62, -416.5, 0.0, 2000001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 3.099, "カリン", 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 190805, 62, -416.5, 0.0, 2000002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 2.801, "カリン", 3, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 190805, 63, -416.5, 0.0, 2000003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 0.0, "カリン", 4, 2, "報酬がもらえますよ！\nチェックしてみてください", 2, 190805, 63, -416.5, 0.0, 2000004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 2.12, "カリン", 5, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 190805, 64, -363.0, 0.0, 2000005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 1.68, "カリン", 6, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 190805, 64, -363.0, 0.0, 2000006);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 2, "2030/01/01 14:59:59", 2.33, "カリン", 7, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 190805, 64, -363.0, 0.0, 2000007);
